    return False

def max_value_on_paths(N: int, grid_values: list) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each cell value can be collected at most once, even if both paths pass through it.
    """
    # Build grid with 1-indexed coordinates
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # dp[i1][i2] = maximum sum when first path is at (i1, j1) and second at (i2, j2)
    # where j1 = k - i1, j2 = k - i2 for current step k
    NEG_INF = -10**15
    dp_prev = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]  # start at (1,1)

    for k in range(2, 2 * N + 1):
        dp_cur = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        i_min = max(1, k - N)
        i_max = min(N, k - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue
                best = NEG_INF
                # consider all combinations of previous moves
                for di1 in (0, 1):  # 0: came from left (i1 same), 1: came from up (i1-1)
                    for di2 in (0, 1):
                        pi1 = i1 - di1
                        pi2 = i2 - di2
                        if pi1 < 1 or pi2 < 1:
                            continue
                        pj1 = (k - 1) - pi1
                        pj2 = (k - 1) - pi2
                        if pj1 < 1 or pj1 > N or pj2 < 1 or pj2 > N:
                            continue
                        prev_val = dp_prev[pi1][pi2]
                        if prev_val == NEG_INF:
                            continue
                        best = max(best, prev_val)
                if best == NEG_INF:
                    continue
                cell_val = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    cell_val += grid[i2][j2]
                dp_cur[i1][i2] = best + cell_val
        dp_prev = dp_cur

    return dp_prev[N][N] if dp_prev[N][N] != NEG_INF else 0

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    first = True
    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if first:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'

        abs_coeff = abs(coeff)

        # Determine variable part
        if degree == 0:
            var_part = ''
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = f'x^{degree}'

        # Determine coefficient part
        if abs_coeff == 1 and degree > 0:
            coeff_part = ''
        else:
            coeff_part = str(abs_coeff)

        term = f"{sign}{coeff_part}{var_part}"
        terms.append(term)
        first = False

    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Check that encoded and original have the same length
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for enc_char, orig_char in zip(encoded, original):
        if enc_char in mapping:
            if mapping[enc_char] != orig_char:
                return "Failed"  # Contradiction
        else:
            mapping[enc_char] = orig_char

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"  # Missing mapping for a character
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.

    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) is used to explore all possible transformations. The function returns the count
    of unique numbers that can be generated from the original number, including the number itself.

    Args:
    - n (int): The original integer number to transform.
    - rules (list of tuples): A list of transformation rules, where each rule is represented
                              as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
    - int: The total count of unique numbers that can be generated.
    """
    start = str(n)
    visited = {start}
    queue = [start]

    # Build a mapping from digit to list of possible replacements
    rule_map = {}
    for x, y in rules:
        rule_map.setdefault(str(x), []).append(str(y))

    while queue:
        current = queue.pop(0)
        for i, ch in enumerate(current):
            if ch in rule_map:
                for replacement in rule_map[ch]:
                    new_num = current[:i] + replacement + current[i+1:]
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)

    return len(visited)

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    if m > sum(a):
        return 0
    dp_prev = [0] * (m + 1)
    dp_prev[0] = 1
    for i in range(n):
        limit = a[i]
        dp_cur = [0] * (m + 1)
        prefix = [0] * (m + 1)
        prefix[0] = dp_prev[0]
        for j in range(1, m + 1):
            prefix[j] = (prefix[j - 1] + dp_prev[j]) % MOD
        for j in range(m + 1):
            low = j - limit
            if low <= 0:
                dp_cur[j] = prefix[j]
            else:
                dp_cur[j] = (prefix[j] - prefix[low - 1]) % MOD
        dp_prev = dp_cur
    return dp_prev[m] % MOD

